import pandas as pd
import plotly.express as px
import plotly.graph_objects as go
import json
import os

def create_report():
    # Read data
    df = pd.read_csv('/app/benchmark/data.csv')

    # Calculate KPIs
    median_coli = df['cost_of_living_index'].median()
    avg_rent_salary = df['rent_to_salary_ratio_pct'].mean()
    pp_gap = df['local_purchasing_power_index'].max() - df['local_purchasing_power_index'].min()
    highest_tier = df['cost_crisis_tier'].max()
    high_crisis_count = len(df[df['cost_crisis_tier'] == highest_tier])
    avg_inflation = df['annual_inflation_rate_2025_pct'].mean()

    # Format KPIs
    kpi_html = f'''
    <div class="kpi-container">
        <div class="kpi-card"><div class="kpi-title">Median Cost of Living Index</div><div class="kpi-value">{median_coli:.1f}</div></div>
        <div class="kpi-card"><div class="kpi-title">Average Rent-to-Salary Ratio</div><div class="kpi-value">{avg_rent_salary:.1f}%</div></div>
        <div class="kpi-card"><div class="kpi-title">Purchasing Power Gap</div><div class="kpi-value">{pp_gap:.1f}</div></div>
        <div class="kpi-card"><div class="kpi-title">High-Crisis City Count</div><div class="kpi-value">{high_crisis_count}</div></div>
        <div class="kpi-card"><div class="kpi-title">Average Annual Inflation</div><div class="kpi-value">{avg_inflation:.2f}%</div></div>
    </div>
    '''

    # 1. Regional Comparison
    fig_region1 = px.box(df, x='region', y='cost_of_living_index', color='region', 
                         title='Cost of Living Index by Region',
                         labels={'cost_of_living_index': 'Cost of Living Index (NY=100)', 'region': 'Region'})
    fig_region1.update_layout(showlegend=False, template='plotly_white')
    html_region1 = fig_region1.to_html(full_html=False, include_plotlyjs='cdn')

    fig_region2 = px.box(df, x='region', y='local_purchasing_power_index', color='region', 
                         title='Local Purchasing Power by Region',
                         labels={'local_purchasing_power_index': 'Purchasing Power (NY=100)', 'region': 'Region'})
    fig_region2.update_layout(showlegend=False, template='plotly_white')
    html_region2 = fig_region2.to_html(full_html=False, include_plotlyjs=False)

    # 2. Affordability and Rent Burden
    # Top 15 cities with highest rent to salary ratio
    top_rent_burden = df.nlargest(15, 'rent_to_salary_ratio_pct')
    fig_aff1 = px.bar(top_rent_burden, x='rent_to_salary_ratio_pct', y='city', orientation='h', 
                      color='region', title='Top 15 Cities by Rent-to-Salary Ratio (%)',
                      labels={'rent_to_salary_ratio_pct': 'Rent-to-Salary Ratio (%)', 'city': 'City'})
    fig_aff1.update_layout(yaxis={'categoryorder':'total ascending'}, template='plotly_white')
    html_aff1 = fig_aff1.to_html(full_html=False, include_plotlyjs=False)

    fig_aff2 = px.scatter(df, x='avg_monthly_net_salary_usd', y='monthly_rent_1br_city_center_usd', 
                          color='cost_crisis_tier', hover_data=['city', 'region', 'rent_to_salary_ratio_pct'],
                          title='Net Salary vs. City Center Rent',
                          labels={'avg_monthly_net_salary_usd': 'Avg Monthly Net Salary (USD)', 
                                  'monthly_rent_1br_city_center_usd': 'Monthly Rent 1BR City Center (USD)',
                                  'cost_crisis_tier': 'Crisis Tier'},
                          color_continuous_scale='Reds')
    fig_aff2.update_layout(template='plotly_white')
    html_aff2 = fig_aff2.to_html(full_html=False, include_plotlyjs=False)

    # 3. Crisis Tier Profiling
    tier_summary = df.groupby('crisis_label')[['cost_of_living_index', 'rent_to_salary_ratio_pct', 'local_purchasing_power_index', 'annual_inflation_rate_2025_pct']].mean().reset_index()
    tier_summary = tier_summary.round(2)
    # Sort by cost of living index descending
    tier_summary = tier_summary.sort_values('cost_of_living_index', ascending=False)

    fig_tier1 = px.scatter_matrix(df, dimensions=['cost_of_living_index', 'rent_to_salary_ratio_pct', 'local_purchasing_power_index'],
                                  color='cost_crisis_tier', title='Crisis Tier Profiles: Core Indicators',
                                  labels={'cost_of_living_index': 'CoL Index', 'rent_to_salary_ratio_pct': 'Rent Burden (%)', 'local_purchasing_power_index': 'Purchasing Power', 'cost_crisis_tier': 'Crisis Tier'})
    fig_tier1.update_layout(template='plotly_white')
    html_tier1 = fig_tier1.to_html(full_html=False, include_plotlyjs=False)

    tier_table = go.Figure(data=[go.Table(
        header=dict(values=['Crisis Label', 'Avg Cost of Living', 'Avg Rent Burden (%)', 'Avg Purchasing Power', 'Avg Inflation (%)'],
                    fill_color='paleturquoise', align='left'),
        cells=dict(values=[tier_summary.crisis_label, tier_summary.cost_of_living_index, tier_summary.rent_to_salary_ratio_pct, 
                           tier_summary.local_purchasing_power_index, tier_summary.annual_inflation_rate_2025_pct],
                   fill_color='lavender', align='left'))
    ])
    tier_table.update_layout(title='Average Indicators per Crisis Tier')
    html_tier_table = tier_table.to_html(full_html=False, include_plotlyjs=False)

    # 4. Inflation and Oil Shock Exposure
    fig_inf1 = px.box(df, x='oil_shock_exposure', y='annual_inflation_rate_2025_pct', color='oil_shock_exposure',
                      title='Annual Inflation Rate by Oil Shock Exposure',
                      labels={'annual_inflation_rate_2025_pct': 'Annual Inflation Rate 2025 (%)', 'oil_shock_exposure': 'Oil Shock Exposure'},
                      category_orders={"oil_shock_exposure": ["Low", "Medium", "High"]})
    fig_inf1.update_layout(showlegend=False, template='plotly_white')
    html_inf1 = fig_inf1.to_html(full_html=False, include_plotlyjs=False)

    fig_inf2 = px.scatter(df, x='cost_of_living_index', y='annual_inflation_rate_2025_pct', color='oil_shock_exposure',
                          size='population_city_millions', hover_name='city',
                          title='Cost of Living vs Inflation (Bubble size: Population)',
                          labels={'cost_of_living_index': 'Cost of Living Index', 'annual_inflation_rate_2025_pct': 'Inflation Rate (%)', 'oil_shock_exposure': 'Oil Shock Exposure'},
                          category_orders={"oil_shock_exposure": ["Low", "Medium", "High"]})
    fig_inf2.update_layout(template='plotly_white')
    html_inf2 = fig_inf2.to_html(full_html=False, include_plotlyjs=False)

    # Assemble HTML
    html = f'''
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <title>Global Cost of Living Crisis Index 2026</title>
        <style>
            :root {{
                --primary: #1e3a8a;
                --secondary: #3b82f6;
                --text-dark: #1f2937;
                --text-light: #6b7280;
                --bg-light: #f3f4f6;
                --border: #e5e7eb;
            }}
            body {{
                font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
                margin: 0;
                padding: 0;
                color: var(--text-dark);
                background-color: #f9fafb;
                line-height: 1.6;
            }}
            .container {{
                max-width: 1200px;
                margin: 0 auto;
                padding: 40px 20px;
            }}
            header {{
                text-align: center;
                margin-bottom: 50px;
            }}
            h1 {{
                color: var(--primary);
                font-size: 2.5rem;
                margin-bottom: 10px;
            }}
            .subtitle {{
                font-size: 1.2rem;
                color: var(--text-light);
            }}
            .kpi-container {{
                display: flex;
                flex-wrap: wrap;
                gap: 20px;
                margin-bottom: 40px;
                justify-content: space-between;
            }}
            .kpi-card {{
                flex: 1;
                min-width: 180px;
                background: white;
                padding: 24px;
                border-radius: 12px;
                box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
                border-top: 4px solid var(--secondary);
                text-align: center;
            }}
            .kpi-title {{
                font-size: 0.9rem;
                text-transform: uppercase;
                letter-spacing: 0.05em;
                color: var(--text-light);
                margin-bottom: 10px;
            }}
            .kpi-value {{
                font-size: 2rem;
                font-weight: 700;
                color: var(--primary);
            }}
            section {{
                background: white;
                padding: 30px;
                border-radius: 12px;
                box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
                margin-bottom: 40px;
            }}
            h2 {{
                color: var(--primary);
                border-bottom: 2px solid var(--bg-light);
                padding-bottom: 10px;
                margin-top: 0;
            }}
            .chart-row {{
                display: flex;
                flex-wrap: wrap;
                gap: 20px;
                margin-top: 20px;
            }}
            .chart-container {{
                flex: 1;
                min-width: 500px;
                border: 1px solid var(--border);
                border-radius: 8px;
                padding: 10px;
            }}
            .summary-text {{
                font-size: 1.05rem;
                margin-bottom: 20px;
            }}
            .recommendations ul {{
                padding-left: 20px;
            }}
            .recommendations li {{
                margin-bottom: 10px;
            }}
        </style>
    </head>
    <body>
        <div class="container">
            <header>
                <h1>Global Cost of Living Crisis Index 2026</h1>
                <div class="subtitle">A Comparative Analysis of Economic Stress Across Cities and Regions</div>
            </header>

            <section id="executive-overview">
                <h2>Executive Overview</h2>
                <div class="summary-text">
                    This report examines cost-of-living pressures, affordability gaps, and economic stress indicators across 80 major cities worldwide in 2026. The analysis highlights severe disparities in housing affordability, purchasing power, and vulnerability to external economic shocks such as inflation and oil price volatility.
                </div>
                {kpi_html}
            </section>

